[IsCgroup2UnifiedMode](https://github.com/opencontainers/runc/blob/b23315bdd99c388f5d0dd3616188729c5a97484a/libcontainer/cgroups/utils.go#L35-L51) function from the [opencontainers/runc/libcontainer](https://github.com/opencontainers/runc/tree/master/libcontainer#libcontainer).

```GO
const (
	unifiedMountpoint = "/sys/fs/cgroup"
)

// IsCgroup2UnifiedMode returns whether we are running in cgroup v2 unified mode.
func IsCgroup2UnifiedMode() bool {
	isUnifiedOnce.Do(func() {
		var st unix.Statfs_t
		err := unix.Statfs(unifiedMountpoint, &st)
		if err != nil {
			if os.IsNotExist(err) && userns.RunningInUserNS() {
				// ignore the "not found" error if running in userns
				logrus.WithError(err).Debugf("%s missing, assuming cgroup v1", unifiedMountpoint)
				isUnified = false
				return
			}
			panic(fmt.Sprintf("cannot statfs cgroup root: %s", err))
		}
		isUnified = st.Type == unix.CGROUP2_SUPER_MAGIC
	})
	return isUnified
}
```

I think we could use the same logic:
 - statfs cgroup mountpoint
 - check the type

I tested this on several servers (some have cgroup v1, some v2) and it works perfectly.
